const int ROWS = 10;
const int COLS = 5;

// 1. Allocate Contiguous Data Block (The core memory)
int* data = (int*)malloc(ROWS * COLS * sizeof(int));

// 2. Allocate Pointer Array (Pointers to the start of each row)
int** array = (int**)malloc(ROWS * sizeof(int*));

// 3. Map Pointers into the Contiguous Block
for (int r = 0; r < ROWS; r++) {
    array[r] = data + r * COLS;
}

// Usage Example (Standard 2D access)
array[1][2] = 42;

// Deallocation (Must free both structures)
free(array);
free(data);
